using System;using System.IO;using System.Text;using System.Collections;using System.Collections.Generic;using System.Reflection;using UnityEngine;using UnityEngine.Rendering;using LWS.TruckBowling;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;
namespace LWS.TruckSports {[DefaultExecutionOrder(-150)]public sealed class SportsProductionWorkload:MonoBehaviour {
#if UNITY_EDITOR || DEVELOPMENT_BUILD
 [RuntimeInitializeOnLoadMethod]static void Boot(){if(Array.IndexOf(Environment.GetCommandLineArgs(),"-tsProductionWorkload")<0)return;var g=new GameObject("Owned rendered production workloads");DontDestroyOnLoad(g);if(!SportsProbeInputIsolation.Active)g.AddComponent<SportsProbeInputIsolation>();g.AddComponent<SportsProductionWorkload>();}
 Keyboard keyboard;InputSettings.BackgroundBehavior background;SportsEventSession match;Func<int,Vector2> ai;Func<int,float,Vector2> aiStep;string folder;int errors,mainRenders,mirrorRenders;bool restored;readonly StringBuilder log=new StringBuilder();readonly Dictionary<string,string> prefs=new Dictionary<string,string>();readonly HashSet<string> had=new HashSet<string>();
 void Check(bool ok,string message){log.AppendLine((ok?"PASS ":"FAIL ")+message);if(!ok)errors++;File.WriteAllText(folder+"/progress.txt",log.ToString());}
 void Error(string message,string stack,LogType type){if(type==LogType.Error||type==LogType.Exception){errors++;log.AppendLine("ERROR "+message);File.WriteAllText(folder+"/progress.txt",log.ToString());}}
 void Rendered(ScriptableRenderContext context,Camera camera){if(match==null)return;foreach(var c in match.cameras)if(c==camera){mainRenders++;if(match is LWS.TruckBuzkashi.BuzMatch&&match.Live&&errors==0){var visibility=c.GetComponent<BowlingCabCamera>();bool clear=visibility!=null&&visibility.exterior!=null&&visibility.exterior.Length>0&&visibility.interior!=null&&visibility.interior.Length>0;if(clear){foreach(var r in visibility.exterior)if(r!=null&&!r.forceRenderingOff)clear=false;foreach(var r in visibility.interior)if(r!=null&&r.forceRenderingOff)clear=false;}if(!clear)Check(false,"Actual Buzkashi owning-camera render must hide its exterior and show its canonical interior");}return;}if(camera.targetTexture!=null&&camera.targetTexture.name.StartsWith("Owned Derby rear mirror",StringComparison.Ordinal))mirrorRenders++;}
 void FixedUpdate(){if(match==null||!match.Live)return;for(int i=0;i<4;i++)match.commands[i]=ai!=null?ai(i):aiStep!=null?aiStep(i,Time.fixedDeltaTime):Vector2.zero;}
