 IEnumerator Sample(string scene,int option){SportsNavigation.LoadSport(scene);yield return null;yield return null;match=FindAnyObjectByType<SportsEventSession>();if(!prefs.ContainsKey(match.PreferenceKey)){if(SportsPrefs.HasKey(match.PreferenceKey))had.Add(match.PreferenceKey);prefs[match.PreferenceKey]=SportsPrefs.GetString(match.PreferenceKey);}match.SetupScreen();match.setup.count=match.MaximumPlayers;match.NormalizeSetup();match.AllBots();match.option=option;match.weather=1;for(int i=0;i<4;i++)match.setup.players[i].source=BowlingSource.Keyboard;if(match is LWS.TruckMattressRacing.MattressMatch)match.option=3;
 var method=match.GetType().GetMethod("AI",BindingFlags.Instance|BindingFlags.NonPublic);ai=null;aiStep=null;if(match is LWS.TruckBungeeDemolition.BungeeMatch){var think=(Action<int>)Delegate.CreateDelegate(typeof(Action<int>),match,match.GetType().GetMethod("Think",BindingFlags.Instance|BindingFlags.NonPublic));var controls=(Vector2[])match.GetType().GetField("ai",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(match);ai=i=>{think(i);return controls[i];};}else if(method==null)throw new MissingMethodException(scene,"AI");else if(method.GetParameters().Length==1)ai=(Func<int,Vector2>)Delegate.CreateDelegate(typeof(Func<int,Vector2>),match,method);else aiStep=(Func<int,float,Vector2>)Delegate.CreateDelegate(typeof(Func<int,float,Vector2>),match,method);Begin();Time.timeScale=1;yield return new WaitForSecondsRealtime(6);Check(match.cameras.Length==4,scene+" actual four-owner viewport workload starts");mainRenders=mirrorRenders=0;int gc=GC.CollectionCount(0);long memory=GC.GetTotalMemory(false);var frames=new List<float>(16384);double total=0;int count=0;float start=Time.realtimeSinceStartup;bool captured=false;while(Time.realtimeSinceStartup-start<60){if(match.Paused)match.Resume();if(match.Finished)Begin();float ms=Time.unscaledDeltaTime*1000;count++;total+=ms;if(frames.Count<16384)frames.Add(ms);if(!captured&&Time.realtimeSinceStartup-start>28){captured=true;ScreenCapture.CaptureScreenshot(folder+"/"+scene+"-four-view-window.png");}yield return null;}frames.Sort();Check(count>100&&mainRenders>400,scene+" sustained60-second workload includes actual automatic four-view rendering");if(scene=="TruckDemolitionDerby")Check(mirrorRenders>100,"actual owned Derby mirror cameras rendered during sustained play");log.AppendLine("PERF scene="+scene+" seconds="+(Time.realtimeSinceStartup-start).ToString("F2")+" frames="+count+" mainRenders="+mainRenders+" mirrorRenders="+mirrorRenders+" meanMS="+(total/Math.Max(1,count)).ToString("F3")+" p95MS="+frames[(int)((frames.Count-1)*.95f)].ToString("F3")+" p99MS="+frames[(int)((frames.Count-1)*.99f)].ToString("F3")+" GC0="+(GC.CollectionCount(0)-gc)+" managedDelta="+(GC.GetTotalMemory(false)-memory)+" GPU="+SystemInfo.graphicsDeviceName+" resolution="+Screen.width+"x"+Screen.height+" timescale=1");File.WriteAllText(folder+"/progress.txt",log.ToString());match.SetupScreen();Begin();yield return null;Check(match.Running&&match.cameras.Length==4,scene+" repeated rematch restores four views");match.SetupScreen();match=null;ai=null;aiStep=null;yield return null;}
 IEnumerator Start(){folder=SportsEvidencePaths.Folder("ProductionWorkloadEvidence");File.WriteAllText(folder+"/result.txt","RUNNING "+DateTime.UtcNow.ToString("O"));background=InputSystem.settings.backgroundBehavior;InputSystem.settings.backgroundBehavior=InputSettings.BackgroundBehavior.IgnoreFocus;keyboard=InputSystem.AddDevice<Keyboard>();InputSystem.EnableDevice(keyboard);InputSystem.QueueStateEvent(keyboard,new KeyboardState());Application.logMessageReceived+=Error;RenderPipelineManager.endCameraRendering+=Rendered;Check(!Application.isEditor&&SystemInfo.graphicsDeviceType!=GraphicsDeviceType.Null,"real rendered Windows player required");if(Application.isEditor)yield break;yield return Sample("TruckDemolitionDerby",0);yield return Sample("TruckMattressRacing",3);yield return Sample("TruckBungeeDemolition",0);yield return Sample("TruckBuzkashi",1);SportsNavigation.FrontEnd();yield return null;yield return null;Check(FindObjectsByType<AudioListener>().Length==1,"heavy scene cycles retain one listener");Restore();log.AppendLine("ERRORS="+errors+". Actual Windows rendering, NWH/PhysX, software-owned AI commands in four human viewports. Whole-frame timings under uncontrolled host load; no isolated GPU benchmark, real hardware or human playtest claim.");File.WriteAllText(folder+"/result.txt",log.ToString());Application.Quit(errors==0?0:2);}
 void Restore(){if(restored)return;restored=true;Application.logMessageReceived-=Error;RenderPipelineManager.endCameraRendering-=Rendered;InputSystem.settings.backgroundBehavior=background;if(keyboard!=null&&keyboard.added)InputSystem.RemoveDevice(keyboard);foreach(var p in prefs)if(had.Contains(p.Key))SportsPrefs.SetString(p.Key,p.Value);else SportsPrefs.DeleteKey(p.Key);SportsPrefs.Save();Time.timeScale=1;}void OnDestroy(){Restore();}
